// Regenerates src/abi.ts from the Foundry build output. Run after changing contracts: `pnpm --filter @reachpot/core gen:abi`.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const out = resolve(here, '../../../contracts/out/Reachpot.sol/Reachpot.json');
const art = JSON.parse(readFileSync(out, 'utf8'));
const src = [
  '// Generated by src/gen-abi.ts from contracts/out — do not edit.',
  `export const reachpotAbi = ${JSON.stringify(art.abi, null, 2)} as const;`,
  '',
  `export const reachpotBytecode = '${art.bytecode.object}' as const;`,
  '',
].join('\n');
writeFileSync(resolve(here, 'abi.ts'), src);
console.log(`wrote src/abi.ts (${art.abi.length} ABI entries)`);
